type MarketplaceIssueReason = "refund" | "fault" | "harassment" | "scam";
type MarketplaceMessage = { author: "buyer" | "seller" | "support"; text: string; attachment?: ChatAttachment };
type MarketplaceConversation = { id: string; productName: string; productPrice: string; productImage: string; sellerHandle: string; buyerName: string; status: "enquiry" | "sold" | "received"; requestStatus: "pending" | "accepted" | "declined" | "blocked"; issue?: { reason: MarketplaceIssueReason; details: string }; messages: MarketplaceMessage[] };
const marketplaceIssueLabel = (language: Language, reason: MarketplaceIssueReason) => reason === "refund" ? tr(language, "Refund request", "退款申请", "退款申請") : reason === "fault" ? tr(language, "Product fault", "商品故障", "商品故障") : reason === "harassment" ? tr(language, "Harassment", "骚扰", "騷擾") : tr(language, "Suspected scam", "疑似诈骗", "疑似詐騙");

function Header({
  language,
  onLanguage,
  location,
  onLocation,
  onNotifications,
  onHome,
  unreadCount,
  darkMode,
  onToggleTheme,
}: {
  language: Language;
  onLanguage: (language: Language) => void;
  location: string;
  onLocation: () => void;
  onNotifications: () => void;
  onHome: () => void;
  unreadCount: number;
  darkMode: boolean;
  onToggleTheme: () => void;
}) {
  const [languageOpen, setLanguageOpen] = useState(false);
  const { width } = useWindowDimensions();
  const compact = width < 380;
  const locationLabel =
    location === "London"
      ? language === "EN"
        ? "London"
        : language === "简体"
          ? "伦敦"
          : "倫敦"
      : location;
  const languageNames: Record<Language, string> = {
    EN: "English",
    简体: "简体中文",
    繁體: "繁體中文",
  };
  return (
    <View
      style={[
        styles.header,
        compact && styles.headerCompact,
        darkMode && styles.darkHeader,
      ]}
    >
      <Pressable
        accessibilityRole="button"
        accessibilityLabel={tr(language, "Go to Home", "返回首页", "返回首頁")}
        onPress={onHome}
      >
        <View
          style={[
            styles.brandLogoFrame,
            compact && styles.brandLogoFrameCompact,
          ]}
        >
          <Image
            source={require("./assets/unimate-logo.png")}
            style={[
              styles.brandLogo,
              compact && styles.brandLogoCompact,
              darkMode && styles.brandLogoDark,
            ]}
            resizeMode="contain"
          />
          {darkMode && (
            <View
              style={[
                styles.brandLogoMarkClip,
                compact && styles.brandLogoMarkClipCompact,
              ]}
            >
              <Image
                source={require("./assets/unimate-logo.png")}
                style={[
                  styles.brandLogoMark,
                  compact && styles.brandLogoMarkCompact,
                ]}
                resizeMode="contain"
              />
            </View>
          )}
        </View>
      </Pressable>
      <View
        style={[styles.headerControls, compact && styles.headerControlsCompact]}
      >
        <Pressable
          accessibilityLabel={
            darkMode
              ? tr(language, "Use light mode", "使用浅色模式", "使用淺色模式")
              : tr(language, "Use dark mode", "使用深色模式", "使用深色模式")
          }
          style={[
            styles.headerIconButton,
            compact && styles.headerIconButtonCompact,
          ]}
          onPress={onToggleTheme}
        >
          <Ionicons
            name={darkMode ? "sunny-outline" : "moon-outline"}
            size={compact ? 18 : 20}
            color={darkMode ? "#FFD166" : palette.navy}
          />
        </Pressable>
        <Pressable
          accessibilityLabel="Notifications"
          style={[
            styles.headerIconButton,
            compact && styles.headerIconButtonCompact,
          ]}
          onPress={onNotifications}
        >
          <Ionicons
            name="notifications-outline"
            size={compact ? 18 : 20}
            color={palette.navy}
          />
          {unreadCount > 0 && (
            <View style={styles.notificationBadge}>
              <Text style={styles.notificationBadgeText}>{unreadCount}</Text>
            </View>
          )}
        </Pressable>
        <Pressable
          accessibilityLabel={`Location: ${locationLabel}`}
          style={[
            styles.headerIconButton,
            compact && styles.headerIconButtonCompact,
          ]}
          onPress={onLocation}
        >
          <Ionicons
            name="location-outline"
            size={compact ? 18 : 20}
            color={palette.navy}
          />
        </Pressable>
        <Pressable
          accessibilityLabel={`Language: ${languageNames[language]}`}
          style={[
            styles.languageIconButton,
            compact && styles.languageIconButtonCompact,
          ]}
          onPress={() => setLanguageOpen(!languageOpen)}
        >
          <Ionicons
            name="globe-outline"
            size={compact ? 18 : 20}
            color={palette.navy}
          />
          <Text style={styles.languageCompact}>{language}</Text>
          <Ionicons
            name={languageOpen ? "chevron-up" : "chevron-down"}
            size={11}
            color={palette.blue}
          />
        </Pressable>
      </View>
      {languageOpen && (
        <View style={styles.languageMenu}>
          {(["EN", "简体", "繁體"] as Language[]).map((item) => (
            <Pressable
              key={item}
              style={[
                styles.languageOption,
                language === item && styles.languageOptionActive,
              ]}
              onPress={() => {
                onLanguage(item);
                setLanguageOpen(false);
              }}
            >
              <Text style={styles.languageCode}>{item}</Text>
              <Text
                style={[
                  styles.languageName,
                  language === item && styles.languageNameActive,
                ]}
              >
                {languageNames[item]}
              </Text>
              {language === item && (
                <Ionicons
                  name="checkmark-circle"
                  size={18}
                  color={palette.blue}
                />
              )}
            </Pressable>
          ))}
        </View>
      )}
    </View>
  );
}

