function AvailabilityCalendar({
  selected,
  onSelect,
  language,
  compact = false,
  bookingMonths = 0,
  isUnavailable,
}: {
  selected: string;
  onSelect: (day: string) => void;
  language: Language;
  compact?: boolean;
  bookingMonths?: number;
  isUnavailable?: (dayKey: string) => boolean;
}) {
  const unavailable: number[] = [];
  const limited: number[] = [];
  const weekdays =
    language === "EN"
      ? ["M", "T", "W", "T", "F", "S", "S"]
      : ["一", "二", "三", "四", "五", "六", "日"];
  const today = useMemo(() => {
    const date = new Date();
    date.setHours(0, 0, 0, 0);
    return date;
  }, []);
  const lastBookableDay = useMemo(() => {
    if (bookingMonths > 0) {
      const lastDayOfTargetMonth = new Date(today.getFullYear(), today.getMonth() + bookingMonths + 1, 0).getDate();
      return new Date(today.getFullYear(), today.getMonth() + bookingMonths, Math.min(today.getDate(), lastDayOfTargetMonth));
    }
    const date = new Date(today);
    date.setDate(date.getDate() + 28);
    return date;
  }, [today, bookingMonths]);
  const [visibleMonth, setVisibleMonth] = useState(() => {
    const date = dateFromKey(selected);
    return new Date(date.getFullYear(), date.getMonth(), 1);
  });
  const monthStart = (date: Date) =>
    new Date(date.getFullYear(), date.getMonth(), 1);
  const canGoBack = visibleMonth.getTime() > monthStart(today).getTime();
  const canGoForward =
    visibleMonth.getTime() < monthStart(lastBookableDay).getTime();
  const firstWeekday = (visibleMonth.getDay() + 6) % 7;
  const numberOfDays = new Date(
    visibleMonth.getFullYear(),
    visibleMonth.getMonth() + 1,
    0,
  ).getDate();
  const days = [
    ...Array(firstWeekday).fill(null),
    ...Array.from({ length: numberOfDays }, (_, index) => index + 1),
  ];
  const monthLabel = visibleMonth.toLocaleDateString(
    language === "EN" ? "en-GB" : language === "简体" ? "zh-CN" : "zh-TW",
    { month: "long", year: "numeric" },
  );
  const moveMonth = (amount: number) =>
    setVisibleMonth(
      new Date(visibleMonth.getFullYear(), visibleMonth.getMonth() + amount, 1),
    );
  return (
    <View style={[styles.calendarCard, compact && styles.calendarCardCompact]}>
      <View
        style={[styles.calendarHead, compact && styles.calendarHeadCompact]}
      >
        <Pressable
          accessibilityLabel={tr(
            language,
            "Previous month",
            "上个月",
            "上個月",
          )}
          disabled={!canGoBack}
          style={[
            styles.calendarArrow,
            compact && styles.calendarArrowCompact,
            !canGoBack && styles.calendarArrowDisabled,
          ]}
          onPress={() => moveMonth(-1)}
        >
          <Ionicons
            name="chevron-back"
            size={compact ? 15 : 18}
            color={canGoBack ? palette.muted : "#C9D2DF"}
          />
        </Pressable>
        <View>
          <Text style={styles.calendarMonth}>{monthLabel}</Text>
          {!compact && (
            <Text style={styles.calendarSub}>
              {tr(
                language,
                bookingMonths > 0 ? "Book up to 2 months ahead" : "Book from today up to 4 weeks ahead",
                bookingMonths > 0 ? "可预约未来2个月" : "可预约今天起未来4周",
                bookingMonths > 0 ? "可預約未來2個月" : "可預約今天起未來4週",
              )}
            </Text>
          )}
        </View>
        <Pressable
          accessibilityLabel={tr(language, "Next month", "下个月", "下個月")}
          disabled={!canGoForward}
          style={[
            styles.calendarArrow,
            compact && styles.calendarArrowCompact,
            !canGoForward && styles.calendarArrowDisabled,
          ]}
          onPress={() => moveMonth(1)}
        >
          <Ionicons
            name="chevron-forward"
            size={compact ? 15 : 18}
            color={canGoForward ? palette.muted : "#C9D2DF"}
          />
        </Pressable>
      </View>
      <View style={styles.weekRow}>
        {weekdays.map((day, index) => (
          <Text key={`${day}-${index}`} style={styles.weekday}>
            {day}
          </Text>
        ))}
      </View>
      <View style={styles.calendarGrid}>
        {days.map((day, index) => {
          if (day === null)
            return (
              <View
                key={`blank-${index}`}
                style={[
                  styles.calendarDay,
                  compact && styles.calendarDayCompact,
                ]}
              />
            );
          const candidate = new Date(
            visibleMonth.getFullYear(),
            visibleMonth.getMonth(),
            day,
          );
          const key = dateKey(candidate);
          const outsideWindow =
            candidate < today || candidate > lastBookableDay;
          const blocked = outsideWindow || unavailable.includes(day) || !!isUnavailable?.(key);
          const isLimited = !outsideWindow && limited.includes(day);
          const isSelected = selected === key;
          return (
            <Pressable
              key={key}
              disabled={blocked}
              accessibilityState={{ disabled: blocked, selected: isSelected }}
              style={[
                styles.calendarDay,
                compact && styles.calendarDayCompact,
                blocked && styles.calendarDayUnavailable,
                isLimited && styles.calendarDayLimited,
                isSelected && styles.calendarDaySelected,
              ]}
              onPress={() => onSelect(key)}
            >
              <Text
                style={[
                  styles.calendarDayText,
                  blocked && styles.calendarDayTextUnavailable,
                  isSelected && styles.calendarDayTextSelected,
                ]}
              >
                {day}
              </Text>
              {isLimited && !isSelected && <View style={styles.limitedDot} />}
            </Pressable>
          );
        })}
      </View>
      {!compact && (
        <View style={styles.calendarLegend}>
          <View style={styles.legendItem}>
            <View
              style={[styles.legendDot, { backgroundColor: palette.green }]}
            />
            <Text style={styles.legendText}>
              {tr(language, "Available", "可预约", "可預約")}
            </Text>
          </View>
          <View style={styles.legendItem}>
            <View style={[styles.legendDot, { backgroundColor: "#F2B94B" }]} />
            <Text style={styles.legendText}>
              {tr(language, "Limited", "少量", "少量")}
            </Text>
          </View>
          <View style={styles.legendItem}>
            <View style={[styles.legendDot, { backgroundColor: "#D6DEE8" }]} />
            <Text style={styles.legendText}>
              {tr(
                language,
                "Outside booking window",
                "不在预约范围内",
                "不在預約範圍內",
              )}
            </Text>
          </View>
        </View>
      )}
    </View>
  );
}

function VisitDateDropdown({
  selected,
  onSelect,
  language,
}: {
  selected: string;
  onSelect: (day: string) => void;
  language: Language;
}) {
  const [open, setOpen] = useState(false);
  const today = useMemo(() => {
    const date = new Date();
    date.setHours(0, 0, 0, 0);
    return date;
  }, []);
  const earliest = useMemo(() => {
    const date = new Date(today);
    date.setFullYear(date.getFullYear() - 1);
    return date;
  }, [today]);
  const [visibleMonth, setVisibleMonth] = useState(
    () => new Date(today.getFullYear(), today.getMonth(), 1),
  );
  const firstWeekday = (visibleMonth.getDay() + 6) % 7;
  const numberOfDays = new Date(
    visibleMonth.getFullYear(),
    visibleMonth.getMonth() + 1,
    0,
  ).getDate();
  const days = [
    ...Array(firstWeekday).fill(null),
    ...Array.from({ length: numberOfDays }, (_, index) => index + 1),
  ];
  const weekdays =
    language === "EN"
      ? ["M", "T", "W", "T", "F", "S", "S"]
      : ["一", "二", "三", "四", "五", "六", "日"];
  const monthLabel = visibleMonth.toLocaleDateString(
    language === "EN" ? "en-GB" : language === "简体" ? "zh-CN" : "zh-TW",
    { month: "long", year: "numeric" },
  );
  const canGoBack =
    new Date(visibleMonth.getFullYear(), visibleMonth.getMonth(), 1) >
    new Date(earliest.getFullYear(), earliest.getMonth(), 1);
  const canGoForward =
    new Date(visibleMonth.getFullYear(), visibleMonth.getMonth(), 1) <
    new Date(today.getFullYear(), today.getMonth(), 1);
  return (
    <View style={styles.visitDateWrap}>
      <Text style={styles.fieldLabel}>
        {tr(language, "Visit date", "到访日期", "到訪日期")}
      </Text>
      <Pressable
        style={styles.visitDateButton}
        accessibilityState={{ expanded: open }}
        onPress={() => setOpen(!open)}
      >
        <View style={{ flexDirection: "row", alignItems: "center", gap: 8 }}>
          <Ionicons name="calendar-outline" size={18} color={palette.blue} />
          <Text style={styles.visitDateValue}>
            {formatBookingDate(selected, language)}
          </Text>
        </View>
        <Ionicons
          name={open ? "chevron-up" : "chevron-down"}
          size={17}
          color={palette.blue}
        />
      </Pressable>
      {open && (
        <View style={styles.visitCalendar}>
          <View style={styles.calendarHead}>
            <Pressable
              disabled={!canGoBack}
              style={[
                styles.calendarArrow,
                !canGoBack && styles.calendarArrowDisabled,
              ]}
              onPress={() =>
                setVisibleMonth(
                  new Date(
                    visibleMonth.getFullYear(),
                    visibleMonth.getMonth() - 1,
                    1,
                  ),
                )
              }
            >
              <Ionicons
                name="chevron-back"
                size={17}
                color={canGoBack ? palette.muted : "#C9D2DF"}
              />
            </Pressable>
            <View>
              <Text style={styles.calendarMonth}>{monthLabel}</Text>
              <Text style={styles.calendarSub}>
                {tr(
                  language,
                  "Select a visit from the past 12 months",
                  "选择过去12个月内的到访日期",
                  "選擇過去12個月內的到訪日期",
                )}
              </Text>
            </View>
            <Pressable
              disabled={!canGoForward}
              style={[
                styles.calendarArrow,
                !canGoForward && styles.calendarArrowDisabled,
              ]}
              onPress={() =>
                setVisibleMonth(
                  new Date(
                    visibleMonth.getFullYear(),
                    visibleMonth.getMonth() + 1,
                    1,
                  ),
                )
              }
            >
              <Ionicons
                name="chevron-forward"
                size={17}
                color={canGoForward ? palette.muted : "#C9D2DF"}
              />
            </Pressable>
          </View>
          <View style={styles.weekRow}>
            {weekdays.map((day, index) => (
              <Text key={`${day}-${index}`} style={styles.weekday}>
                {day}
              </Text>
            ))}
          </View>
          <View style={styles.calendarGrid}>
            {days.map((day, index) => {
              if (day === null)
                return (
                  <View
                    key={`visit-blank-${index}`}
                    style={styles.calendarDay}
                  />
                );
              const candidate = new Date(
                visibleMonth.getFullYear(),
                visibleMonth.getMonth(),
                day,
              );
              const key = dateKey(candidate);
              const disabled = candidate > today || candidate < earliest;
              const active = key === selected;
              return (
                <Pressable
                  key={key}
                  disabled={disabled}
                  style={[
                    styles.calendarDay,
                    disabled && styles.calendarDayUnavailable,
                    active && styles.calendarDaySelected,
                  ]}
                  onPress={() => {
                    onSelect(key);
                    setOpen(false);
                  }}
                >
                  <Text
                    style={[
                      styles.calendarDayText,
                      disabled && styles.calendarDayTextUnavailable,
                      active && styles.calendarDayTextSelected,
                    ]}
                  >
                    {day}
                  </Text>
                </Pressable>
              );
            })}
          </View>
        </View>
      )}
    </View>
  );
}

